  1	import java.util.Arrays;
  2	import java.util.Comparator;
  3	import java.util.Objects;
  4	
  5	public class ActivitySelection {
  6	    private static final Comparator<Activity> BY_FINISH_TIME =
  7	        Comparator.comparingInt(Activity::finishTime);
  8	
  9	    private ActivitySelection() {
 10	    }
 11	
 12	    public static int activitySelection(int[] start, int[] finish) {
 13	        return maximumCompatibleActivityCount(start, finish);
 14	    }
 15	
 16	    public static int maximumCompatibleActivityCount(int[] start, int[] finish) {
 17	        return buildSelectionResult(start, finish).count();
 18	    }
 19	
 20	    public static int[][] selectMaximumCompatibleActivities(int[] start, int[] finish) {
 21	        return buildSelectionResult(start, finish).activities();
 22	    }
 23	
 24	    public static SelectionResult buildSelectionResult(int[] start, int[] finish) {
 25	        return ActivitySchedule.fromParallelArrays(start, finish).selectionResult();
 26	    }
 27	
 28	    public static void main(String[] args) {
 29	        int[] start = {1, 3, 0, 5, 8, 5};
 30	        int[] finish = {2, 4, 6, 7, 9, 9};
 31	
 32	        System.out.println(activitySelection(start, finish));
 33	    }
 34	
 35	    private static final class Activity {
 36	        private final int startTime;
 37	        private final int finishTime;
 38	
 39	        private Activity(int startTime, int finishTime) {
 40	            this.startTime = startTime;
 41	            this.finishTime = finishTime;
 42	        }
 43	
 44	        private int finishTime() {
 45	            return finishTime;
 46	        }
 47	
 48	        private boolean canFollow(Activity other) {
 49	            return startTime > other.finishTime;
 50	        }
 51	
 52	        private ActivitySlot toSlot() {
 53	            return new ActivitySlot(startTime, finishTime);
 54	        }
 55	
 56	        @Override
 57	        public String toString() {
 58	            return "[" + startTime + ", " + finishTime + "]";
 59	        }
 60	    }
 61	
 62	    private static final class ActivitySchedule {
 63	        private final Activity[] activities;
 64	
 65	        private ActivitySchedule(Activity[] activities) {
 66	            this.activities = activities;
 67	        }
 68	
 69	        private static ActivitySchedule fromParallelArrays(int[] start, int[] finish) {
 70	            validateInputs(start, finish);
 71	
 72	            Activity[] activities = new Activity[start.length];
 73	            for (int i = 0; i < start.length; i++) {
 74	                activities[i] = new Activity(start[i], finish[i]);
 75	            }
 76	
 77	            Arrays.sort(activities, BY_FINISH_TIME);
 78	            return new ActivitySchedule(activities);
 79	        }
 80	
 81	        private SelectionResult selectionResult() {
 82	            Activity[] selectedActivities = selectCompatibleActivities();
 83	            ActivitySlot[] selectedSlots = new ActivitySlot[selectedActivities.length];
 84	            for (int i = 0; i < selectedActivities.length; i++) {
 85	                selectedSlots[i] = selectedActivities[i].toSlot();
 86	            }
 87	            return new SelectionResult(selectedSlots);
 88	        }
 89	
 90	        private Activity[] selectCompatibleActivities() {
 91	            if (activities.length == 0) {
 92	                return new Activity[0];
 93	            }
 94	
 95	            Activity[] selectedActivities = new Activity[activities.length];
 96	            int selectedCount = 1;
 97	            Activity lastSelected = activities[0];
 98	            selectedActivities[0] = lastSelected;
 99	
100	            // Greedily keep the earliest-finishing compatible activity.
101	            for (int i = 1; i < activities.length; i++) {
102	                Activity current = activities[i];
103	                if (current.canFollow(lastSelected)) {
104	                    selectedActivities[selectedCount] = current;
105	                    selectedCount++;
106	                    lastSelected = current;
107	                }
108	            }
109	
110	            return Arrays.copyOf(selectedActivities, selectedCount);
111	        }
112	
113	        private static void validateInputs(int[] start, int[] finish) {
114	            Objects.requireNonNull(start, "start must not be null");
115	            Objects.requireNonNull(finish, "finish must not be null");
116	
117	            if (start.length != finish.length) {
118	                throw new IllegalArgumentException("start and finish must have the same length");
119	            }
120	        }
121	    }
122	
123	    public static final class SelectionResult {
124	        private final ActivitySlot[] activities;
125	
126	        private SelectionResult(ActivitySlot[] activities) {
127	            this.activities = copyActivities(activities);
128	        }
129	
130	        public int count() {
131	            return activities.length;
132	        }
133	
134	        public ActivitySlot[] selectedActivities() {
135	            return copyActivities(activities);
136	        }
137	
138	        public int[][] activities() {
139	            int[][] pairs = new int[activities.length][2];
140	            for (int i = 0; i < activities.length; i++) {
141	                pairs[i] = activities[i].toPair();
142	            }
143	            return pairs;
144	        }
145	
146	        private static ActivitySlot[] copyActivities(ActivitySlot[] activities) {
147	            ActivitySlot[] copy = new ActivitySlot[activities.length];
148	            for (int i = 0; i < activities.length; i++) {
149	                copy[i] = activities[i];
150	            }
151	            return copy;
152	        }
153	    }
