155	    public static final class ActivitySlot {
156	        private final int startTime;
157	        private final int finishTime;
158	
159	        private ActivitySlot(int startTime, int finishTime) {
160	            this.startTime = startTime;
161	            this.finishTime = finishTime;
162	        }
163	
164	        public int startTime() {
165	            return startTime;
166	        }
167	
168	        public int finishTime() {
169	            return finishTime;
170	        }
171	
172	        private int[] toPair() {
173	            return new int[] {startTime, finishTime};
174	        }
175	
176	        @Override
177	        public String toString() {
178	            return "[" + startTime + ", " + finishTime + "]";
179	        }
180	    }
181	}

