  3	public class ActivitySelectionTest {
  4	    public static void main(String[] args) {
  5	        SelectionCase[] selectionCases = {
  6	            new SelectionCase(
  7	                4,
  8	                new int[] {1, 3, 0, 5, 8, 5},
  9	                new int[] {2, 4, 6, 7, 9, 9},
 10	                new int[][] {{1, 2}, {3, 4}, {5, 7}, {8, 9}},
 11	                "selects the expected number of compatible activities"
 12	            ),
 13	            new SelectionCase(
 14	                0,
 15	                new int[] {},
 16	                new int[] {},
 17	                new int[][] {},
 18	                "returns zero for empty input"
 19	            ),
 20	            new SelectionCase(
 21	                1,
 22	                new int[] {1, 2},
 23	                new int[] {2, 3},
 24	                new int[][] {{1, 2}},
 25	                "preserves the strict compatibility rule when activities touch"
 26	            )
 27	        };
 28	
 29	        for (SelectionCase testCase : selectionCases) {
 30	            assertSelectionCount(testCase);
 31	            assertSelectedActivities(testCase);
 32	            assertSelectedActivitySlots(testCase);
 33	            assertSelectionResult(testCase);
 34	            assertLegacyAlias(testCase);
 35	        }
 36	
 37	        assertThrows(
 38	            IllegalArgumentException.class,
 39	            () -> ActivitySelection.activitySelection(new int[] {1, 2}, new int[] {3}),
 40	            "rejects mismatched input lengths"
 41	        );
 42	
 43	        assertThrows(
 44	            NullPointerException.class,
 45	            () -> ActivitySelection.activitySelection(null, new int[] {}),
 46	            "rejects null start input"
 47	        );
 48	
 49	        assertThrows(
 50	            NullPointerException.class,
 51	            () -> ActivitySelection.activitySelection(new int[] {}, null),
 52	            "rejects null finish input"
 53	        );
 54	    }
 55	
 56	    private static void assertLegacyAlias(SelectionCase testCase) {
 57	        assertEquals(
 58	            ActivitySelection.maximumCompatibleActivityCount(
 59	                testCase.startTimes(),
 60	                testCase.finishTimes()
 61	            ),
 62	            ActivitySelection.activitySelection(testCase.startTimes(), testCase.finishTimes()),
 63	            testCase.message() + " through the legacy alias"
 64	        );
 65	    }
 66	
 67	    private static void assertSelectionResult(SelectionCase testCase) {
 68	        ActivitySelection.SelectionResult result =
 69	            ActivitySelection.buildSelectionResult(testCase.startTimes(), testCase.finishTimes());
 70	
 71	        assertEquals(
 72	            testCase.expectedCount(),
 73	            result.count(),
 74	            testCase.message() + " with the expected result count"
 75	        );
 76	        assertDeepEquals(
 77	            testCase.expectedActivities(),
 78	            result.activities(),
 79	            testCase.message() + " with the expected result activities"
 80	        );
 81	    }
 82	
 83	    private static void assertSelectedActivitySlots(SelectionCase testCase) {
 84	        ActivitySelection.SelectionResult result =
 85	            ActivitySelection.buildSelectionResult(testCase.startTimes(), testCase.finishTimes());
 86	
 87	        ActivitySelection.ActivitySlot[] slots = result.selectedActivities();
 88	        int[][] actualActivities = new int[slots.length][2];
 89	        for (int i = 0; i < slots.length; i++) {
 90	            actualActivities[i][0] = slots[i].startTime();
 91	            actualActivities[i][1] = slots[i].finishTime();
 92	        }
 93	
 94	        assertDeepEquals(
 95	            testCase.expectedActivities(),
 96	            actualActivities,
 97	            testCase.message() + " with the expected slot objects"
 98	        );
 99	    }
100	
101	    private static void assertSelectedActivities(SelectionCase testCase) {
102	        assertDeepEquals(
103	            testCase.expectedActivities(),
104	            ActivitySelection.selectMaximumCompatibleActivities(
105	                testCase.startTimes(),
106	                testCase.finishTimes()
107	            ),
108	            testCase.message() + " with the expected chosen activities"
109	        );
110	    }
111	
112	    private static void assertSelectionCount(SelectionCase testCase) {
113	        assertEquals(
114	            testCase.expectedCount(),
115	            ActivitySelection.maximumCompatibleActivityCount(
116	                testCase.startTimes(),
117	                testCase.finishTimes()
118	            ),
119	            testCase.message()
120	        );
121	    }
122	
123	    private static void assertDeepEquals(int[][] expected, int[][] actual, String message) {
124	        if (!Arrays.deepEquals(expected, actual)) {
125	            throw new AssertionError(
126	                message
127	                    + ": expected "
128	                    + Arrays.deepToString(expected)
129	                    + " but got "
130	                    + Arrays.deepToString(actual)
131	            );
132	        }
133	    }
134	
135	    private static void assertEquals(int expected, int actual, String message) {
136	        if (expected != actual) {
137	            throw new AssertionError(message + ": expected " + expected + " but got " + actual);
138	        }
139	    }
140	
141	    private static void assertThrows(
142	        Class<? extends Throwable> expected,
143	        ThrowingRunnable runnable,
144	        String message
145	    ) {
146	        try {
147	            runnable.run();
148	        } catch (Throwable actual) {
149	            if (expected.isInstance(actual)) {
150	                return;
151	            }
152	            throw new AssertionError(
153	                message + ": expected " + expected.getSimpleName() + " but got " + actual.getClass().getSimpleName(),
154	                actual
155	            );
156	        }
157	
158	        throw new AssertionError(message + ": expected " + expected.getSimpleName() + " to be thrown");
159	    }
160	
161	    @FunctionalInterface
162	    private interface ThrowingRunnable {
163	        void run() throws Throwable;
164	    }
165	
166	    private record SelectionCase(
167	        int expectedCount,
168	        int[] startTimes,
169	        int[] finishTimes,
170	        int[][] expectedActivities,
171	        String message
172	    ) {
173	    }
174	}

